save(345,dict(paragraphs=["Mallika Tripathi writes poetry alongside a career in education. Literary profiles connect her with the Department of Applied Science and Humanities at Feroze Gandhi Institute of Engineering and Technology, Raebareli. Her writing spans Hindi and English, with collections including ‘Oh Son! My Sun!’ and ‘Whispers of the Soul’.","Her Kabita Live poem ‘Angel’ imagines a figure who rises beyond anguish without surrendering to it. Ashes, light and clear sight give the poem its movement from suffering towards endurance. The angel’s distance from worldly attachment is paired with an embrace of others, making compassion and inward strength central to the portrait."],sources=[source('LitStream: Dr Mallika Tripathi','https://www.litstream.in/2025/12/meet-litstream-literary-voices-dr.html',['Bilingual poet; FGIET Applied Science and Humanities affiliation; books Oh Son! My Sun! and Whispers of the Soul.']),source('Boloji: Mallika Tripathi','https://www.boloji.com/writers/5359/mallika',['Matching academic affiliation and literary work establish identity beyond name.'])],identity_match='Captured biography and external literary profiles agree on FGIET Raebareli, humanities department and educator/poet identity. Unrelated namesakes excluded.',poems_read=[dict(id=421,title='Angel',basis='Full English original read; ashes, spiritual endurance, vision, truth and compassion.')],limitations=['No unsupported awards, years-of-service total or personal religious beliefs added. No publisher book link confirmed in this pass.'],research_leads=[dict(url='https://euacademic.org/UploadArticle/2410.pdf',access='search_index_excerpt; www direct open failed',finding='March 2016 academic paper author note matches FGIET Head of Humanities and Oh Son! My Sun!.')],next_action='Independent factual review and publisher book-link verification.'))
